package remframework.geometry.discovery;

import org.joml.Vector3d;
import org.junit.jupiter.api.Test;
import remframework.geometry.discovery.configuration.*;
import remframework.geometry.discovery.experiment.*;
import remframework.geometry.discovery.realization.session.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class Stage2NumericalDiagnosticsTest {
    private static final Fixture FIXTURE=fixture();
    @Test void stagnationUsesMeasuredSlidingWindow(){StagnationDetector plateau=new StagnationDetector(5,.01);StagnationStatus status=null;for(int i=0;i<5;i++)status=plateau.add(1-i*1e-5,1e-8,false);assertEquals(StagnationClass.PLATEAUED,status.classification());StagnationDetector progress=new StagnationDetector(5,.01);for(int i=0;i<5;i++)status=progress.add(1-i*.1,.01,false);assertEquals(StagnationClass.PROGRESSING,status.classification());assertEquals(StagnationClass.NUMERICALLY_UNSTABLE,progress.add(Double.NaN,0,false).classification());assertEquals(StagnationClass.CONVERGED,new StagnationDetector(5,.01).add(1,0,true).classification());}

    @Test void gaugeAnchorsUseAnActualTopologyEdge(){Fixture fixture=FIXTURE;IncrementalSession session=new IncrementalSession(fixture.configuration,request(fixture,42,10,conditions(0)));List<Vector3d> p=session.initialCoordinates();int second=fixture.configuration.adjacency().get(0).stream().mapToInt(Integer::intValue).min().orElseThrow();assertEquals(1,p.get(0).distance(p.get(second)),1e-12);assertTrue(fixture.configuration.edges().stream().anyMatch(e->e.undirectedKey()==new DiscoveryConnection(0,second).undirectedKey()));}

    @Test void faceObjectivesAreRigidMotionInvariant(){Fixture fixture=FIXTURE;IncrementalSession session=new IncrementalSession(fixture.configuration,request(fixture,42,10,conditions(4)));Vector3d axis=new Vector3d(.2,.7,.4).normalize();List<DynamicElasticNode> original=nodes(session.initialCoordinates()),moved=nodes(session.initialCoordinates().stream().map(p->new Vector3d(p).rotateAxis(.73,axis.x,axis.y,axis.z).add(4,-3,2)).toList());DynamicElasticThreeDConstraints constraints=new DynamicElasticThreeDConstraints(fixture.faces,conditions(4),ThreeDConstraintStrengths.defaults(),1);FaceObjectiveDiagnostics a=constraints.objectiveDiagnostics(original),b=constraints.objectiveDiagnostics(moved);assertEquals(a.totalContribution(),b.totalContribution(),1e-9);assertEquals(a.planarityRms(),b.planarityRms(),1e-9);assertEquals(a.angleRms(),b.angleRms(),1e-9);}

    @Test void eachRequiredFaceGradientIsADescentDirection(){Fixture fixture=FIXTURE;IncrementalSession session=new IncrementalSession(fixture.configuration,request(fixture,42,10,conditions(3)));for(int component=1;component<=4;component++){ThreeDExperimentConditions mode=conditions(component);DynamicElasticThreeDConstraints constraints=new DynamicElasticThreeDConstraints(fixture.faces,mode,ThreeDConstraintStrengths.defaults(),1);List<DynamicElasticNode> nodes=nodes(session.initialCoordinates());double before=constraints.objectiveDiagnostics(nodes).totalContribution();Map<Integer,Vector3d> forces=new HashMap<>();nodes.forEach(n->forces.put(n.id(),new Vector3d()));constraints.addForces(nodes,forces);nodes.forEach(n->n.position().add(new Vector3d(forces.get(n.id())).mul(1e-5)));double after=constraints.objectiveDiagnostics(nodes).totalContribution();assertTrue(after<=before+1e-10,"component "+component+" must descend");}}

    @Test void boundedTwentyVertexRunRemainsFiniteAndReportsObjectiveHistoryWithoutChangingFaces(){Fixture fixture=FIXTURE;String encoded=fixture.configuration.provenance().get("combinatorialFaces");IncrementalSession session=new IncrementalSession(fixture.configuration,request(fixture,42,1000,conditions(0)));for(int i=0;i<500;i++)session.step();ConstraintObjectiveDiagnostics after=session.objectiveDiagnostics();assertTrue(Double.isFinite(after.totalObjective()));assertNotNull(session.stagnationStatus());assertEquals(encoded,fixture.configuration.provenance().get("combinatorialFaces"));assertEquals(12,fixture.faces.size());}

    private static ThreeDExperimentConditions conditions(int component){return new ThreeDExperimentConditions(component==1||component==0?FacePlanarityMode.REQUIRE_PLANAR_FACES:FacePlanarityMode.MEASURE_ONLY,component==2||component==0?FaceAngleConditionMode.REQUIRE_EQUAL_ANGLES_WITHIN_EACH_FACE:FaceAngleConditionMode.MEASURE_ONLY,component==3?DihedralConditionMode.REQUIRE_EQUAL_DIHEDRAL_ANGLES:DihedralConditionMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,component==4?FacePlaneRadiusMode.REQUIRE_EQUAL_FACE_PLANE_RADII:FacePlaneRadiusMode.MEASURE_ONLY,RegularityMode.MEASURE_ONLY,GeometryCenterDefinition.VERTEX_CENTROID,1e-4,1e-3,1e-3);}
    private static List<DynamicElasticNode> nodes(List<Vector3d> coordinates){List<DynamicElasticNode> result=new ArrayList<>();for(int i=0;i<coordinates.size();i++)result.add(new DynamicElasticNode(i,coordinates.get(i),new Vector3d(),false));return result;}
    private static TestRequest request(Fixture f,long seed,int limit,ThreeDExperimentConditions conditions){return new TestRequest(f.configuration.id(),GeometryEmbeddingDimension.THREE_D,1,seed,1,null,GeometrySymmetryPolicy.MEASURE_ONLY,limit,ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME,null,null,null,1e-3,1e-7,1e-9,1e-6,null,0,0,conditions,BenchmarkPreset.NONE,ThreeDConstraintStrengths.defaults()).withFaceComposition(FaceComposition.uniform(5)).withParameterDerivation(f.request);}
    private static Fixture fixture(){ConfigurationRequest request=ConfigurationRequest.byFaceCount(12,3,GeometryEmbeddingDimension.THREE_D,ExperimentProfile.CONVEX_POLYHEDRAL_VOLUME).withFaceComposition(FaceComposition.uniform(5));List<DiscoveryConnection> edges=remframework.geometry.discovery.reference.ReferenceTopologyRecognizer.dodecahedronGraphEdges();List<List<Integer>> faces=List.of(List.of(0,1,2,12,10),List.of(0,1,11,19,9),List.of(0,9,8,18,10),List.of(1,2,3,13,11),List.of(2,3,4,14,12),List.of(3,4,5,15,13),List.of(4,5,6,16,14),List.of(5,6,7,17,15),List.of(6,7,8,18,16),List.of(7,8,9,19,17),List.of(10,12,14,16,18),List.of(11,13,15,17,19));String encoded=remframework.geometry.discovery.configuration.CombinatorialFaceComplex.encode(faces);GeometryConfigurationDiagnostic diagnostic=GeometryConfigurationDiagnostic.info(GeometryConfigurationStage.GRAPH_GENERATION,GeometryConfigurationStatusCode.GENERATED,"Generated","Test fixture retains the exact reference-isomorphic topology and face complex.");Configuration configuration=new Configuration(new ConfigurationId("cfg-b10320c7778b"),20,3,edges,null,"reference-test","reference-test",120,GraphSymmetryClassification.HIGHLY_SYMMETRIC,true,0,"TEST",true,GeometryConfigurationStatus.of(diagnostic),List.of(diagnostic),java.time.Instant.EPOCH,Map.of("combinatorialFaces",encoded));return new Fixture(request,configuration,faces);}
    private record Fixture(ConfigurationRequest request,Configuration configuration,List<List<Integer>> faces){}
}
